        private sealed class Select14ClearanceTranscript : INavMotionClearance
        {
            internal sealed class Call {public int Row;public NavPoint End;public bool Allowed;}
            internal readonly System.Collections.Generic.List<Call> Calls=new System.Collections.Generic.List<Call>();
            private readonly INavMotionClearance source;private bool replay;internal int Consumed,UnderlyingCalls;
            internal Select14ClearanceTranscript(INavMotionClearance source){this.source=source;}
            internal void Replay(){replay=true;Consumed=0;}
            public bool ClearMotion(int actor,NavPoint end){
                if(!replay){UnderlyingCalls++;bool allowed=source.ClearMotion(actor,end);Calls.Add(new Call{Row=actor,End=end,Allowed=allowed});return allowed;}
                Assert.Less(Consumed,Calls.Count,"trace requested an extra clearance call");var call=Calls[Consumed++];Assert.AreEqual(call.Row,actor);Assert.AreEqual(call.End,end,"source-exact clearance call order and endpoint");return call.Allowed;
            }
        }
