                for(int k=0;k<count;k++){var b=bodies[neighbors[row*NavCrowdMotion.NeighborCapacity+k]];double radius=a.Radius+b.Radius;var preferred=Preferred(b);double gap=NavCrowdMotion.ClosestSquared(Subtract(a.Position,b.Position),Subtract(velocity,preferred),profile.CrowdLookaheadSeconds);double term=Math.Max(0,1-gap/(radius*radius));risk=Math.Max(risk,term);values.Add(new System.Collections.Generic.KeyValuePair<int,double>(b.Id,term));terms.Add(new{Id=b.Id,b.Active,b.Yielding,PreferredVelocity=preferred,GapSquared=gap,RadiusSquared=radius*radius,Risk=term});}
                double original=(double)typeof(NavCrowdMotion).GetMethod("Risk",System.Reflection.BindingFlags.Static|System.Reflection.BindingFlags.NonPublic).Invoke(null,new object[]{bodies,row,velocity,neighbors,count,profile.CrowdLookaheadSeconds});Assert.AreEqual(original,risk,"pure arithmetic Risk reconstruction must be exact");
                explanation=new{Value=risk,MaxNeighborIds=values.Where(pair=>pair.Value==risk).Select(pair=>pair.Key).ToArray(),Terms=terms};return risk;
            }
