                for(int k=0;k<count;k++){var b=bodies[neighbors[row*NavCrowdMotion.NeighborCapacity+k]];if(b.Active){terms.Add(new{Id=b.Id,Check="SKIPPED active peer"});continue;}double radius=a.Radius+b.Radius;double gap=NavCrowdMotion.ClosestSquared(Subtract(a.Position,b.Position),velocity,dt);bool clear=!(gap<radius*radius-1e-9);terms.Add(new{Id=b.Id,Check="EXECUTED",GapSquared=gap,Threshold=radius*radius-1e-9,Clear=clear});if(!clear){allowed=false;break;}}
