                var preferred=Preferred(a);double bestRisk=ExplainedRisk(default,out var initialRisk),bestError=a.Speed*a.Speed;bool futureStaticMove=false,won=false;
                events.Add(new{Event="InitialWait",Risk=initialRisk,BestRisk=bestRisk,BestError=bestError,Turning=turning,PreferredVelocity=preferred});
