                            double incumbentRisk=bestRisk,incumbentError=bestError;bool incumbentWon=won,priorFuture=futureStaticMove;bool futureAvailable=false;bool? futureClearance=null,endClearance=null;object staticCheck=null,riskDetails=null;double? risk=null,error=null;string decision=null;int callStart=transcript.Consumed;
                            if(!aligned||!futureStaticMove){futureClearance=transcript.ClearMotion(row,futureEnd);if(futureClearance==true)futureAvailable=StaticPeers(eventual,out staticCheck);}
                            if(futureAvailable)futureStaticMove=true;
                            if(!aligned&&!futureAvailable)decision="REJECT unaligned and no physically available future";
                            else{
