                                if(endClearance!=true)decision="REJECT actual endpoint clearance";
                                else{
                                    risk=ExplainedRisk(eventual,out riskDetails);double ex=eventual.X-preferred.X,ez=eventual.Z-preferred.Z;error=ex*ex+ez*ez;
                                    if(pass==1&&error.Value>=a.Speed*a.Speed-1e-12)decision="REJECT second-pass error is non-improving";
                                    else if(risk.Value>bestRisk+1e-12)decision="REJECT risk exceeds incumbent plus epsilon";
