                        }
                    }
                }
                result.Blocked=!futureStaticMove;bool activeNeighbor=false;for(int k=0;k<count;k++)if(bodies[neighbors[row*NavCrowdMotion.NeighborCapacity+k]].Active){activeNeighbor=true;break;}result.StaticNoWinner=!won&&turning.Equals(a.Heading)&&!result.Blocked&&!activeNeighbor;
                Assert.AreEqual(transcript.Calls.Count,transcript.Consumed,"trace must consume exactly the ordinary Select clearance transcript");Assert.AreEqual(transcript.Calls.Count,transcript.UnderlyingCalls,"no extra underlying clearance calls in replay");Assert.AreEqual(actual,result,"candidate-level helper must equal ONE actual second Select on identical inputs");equal=true;return result;
            }finally{
                System.IO.File.WriteAllText(System.IO.Path.Combine(output,"select14-second-candidates.json"),Newtonsoft.Json.JsonConvert.SerializeObject(new{Actor=a.Id,Phase="SECOND Select after real yield activation in reconstructed frame",Runtime="afc976059f4e81a41c31c95846e458028eb6e1b1",Profile=new{profile.ProfileId,profile.Revision,profile.ForwardAlignmentAngle,profile.CrowdHeadingIntervals,profile.CrowdSpeedBands,profile.CrowdLookaheadSeconds,profile.CrowdNeighborCap},Dt=dt,TechnicalSourceThresholds=new{RankEpsilon=1e-12,PeerSweepEpsilon=1e-9},Inputs=bodies.Select(body=>new{body.Id,body.Position,body.Target,body.Heading,body.Radius,body.Speed,body.TurnSpeed,body.Active,body.Potential,body.Yielding,body.YieldLabel}).ToArray(),NeighborIds=Enumerable.Range(0,Math.Max(0,count)).Select(k=>bodies[neighbors[row*NavCrowdMotion.NeighborCapacity+k]].Id).ToArray(),Events=events,WinnerIndex=winner,ActualSelect=Proposal(actual),TracedSelect=Proposal(result),ActualSelectEqualsTrace=equal,RealClearanceCalls=transcript.Calls,ReplayConsumed=transcript.Consumed,UnderlyingClearanceCalls=transcript.UnderlyingCalls,ExtraUnderlyingClearanceCalls=transcript.UnderlyingCalls-transcript.Calls.Count,Qualification="Must additionally pass all14 comparison against ONE actual Compute and strict footer"},Newtonsoft.Json.Formatting.Indented));
            }
