        // Diagnostic only: walk fields, including facade backing fields and scope
        // birth journals. Never call a production getter to discover ownership.
        private sealed class LedgerOriginCensus
        {
            private sealed class Identity : System.Collections.Generic.IEqualityComparer<object>
            {
                public new bool Equals(object a,object b)=>ReferenceEquals(a,b);
                public int GetHashCode(object value)=>System.Runtime.CompilerServices.RuntimeHelpers.GetHashCode(value);
            }
            private sealed class Row
            {
                public int Id,References;public string Type,Path;public long StorageBytes;
            }
            private readonly NavigationSession session;private readonly NavigationRetentionBudget budget;private readonly string output;
            private readonly System.Collections.Generic.Dictionary<object,int> identities=new System.Collections.Generic.Dictionary<object,int>(new Identity());
            private readonly System.Collections.Generic.Dictionary<int,NavOwnedStorage> known=new System.Collections.Generic.Dictionary<int,NavOwnedStorage>();
            private System.Collections.Generic.Dictionary<int,Row> previous=new System.Collections.Generic.Dictionary<int,Row>();
            private long previousPhysical,previousReachable;private int sequence;
            private const System.Reflection.BindingFlags Flags=System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.Public|System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.DeclaredOnly;
            private static readonly System.Reflection.FieldInfo Refs=typeof(NavOwnedStorage).GetField("references",Flags),Ledger=typeof(NavOwnedStorage).GetField("ledger",Flags);
            internal LedgerOriginCensus(NavigationSession session,string output){this.session=session;budget=session.PhysicalHostBudget;this.output=output;}
            internal void Checkpoint(string phase,params object[] privateRoots)
            {
                long physical=budget.PhysicalBytes,held=budget.HeldBytes;int scopes=budget.ActiveScopes;
                var seen=new System.Collections.Generic.HashSet<object>(new Identity());
                var queue=new System.Collections.Generic.Queue<System.Collections.Generic.KeyValuePair<string,object>>();
                var rows=new System.Collections.Generic.Dictionary<int,Row>();
                void Add(string path,object value){if(value!=null)queue.Enqueue(new System.Collections.Generic.KeyValuePair<string,object>(path,value));}
                Add("session",session);for(int i=0;i<privateRoots.Length;i++)Add("private["+i+"]",privateRoots[i]);
                while(queue.Count>0){var item=queue.Dequeue();object value=item.Value;Type type=value.GetType();
                    if(type.IsPrimitive||type.IsEnum||value is string||value is decimal||value is Delegate||value is Type||value is System.Reflection.MemberInfo||value is NavigationRetentionBudget)continue;
                    if(!seen.Add(value))continue;
                    if(value is NavOwnedStorage owner){
                        // A dead birth may still link the rest of the journal.
                        Add(item.Key+".BirthNext",owner.BirthNext);
                        if(!identities.TryGetValue(owner,out int id)){id=identities.Count+1;identities.Add(owner,id);known.Add(id,owner);}
                        int references=(int)Refs.GetValue(owner);
                        if(references<=0)continue;
                        if(ReferenceEquals(Ledger.GetValue(owner),budget))rows.Add(id,new Row{Id=id,References=references,Type=type.FullName,StorageBytes=owner.StorageBytes,Path=item.Key});
                    }
                    if(value is Array array){int index=0;foreach(var entry in array)Add(item.Key+"["+(index++)+"]",entry);continue;}
                    // Session/private graphs contain ordinary collection wrappers.
                    // Other framework objects have no navigation payload edges.
                    if(type.Assembly==typeof(object).Assembly&&!(type.Namespace??"").StartsWith("System.Collections",StringComparison.Ordinal))continue;
                    for(Type current=type;current!=null&&current!=typeof(object);current=current.BaseType)
                        foreach(var field in current.GetFields(Flags)){
                            if(current==typeof(NavOwnedStorage)&&(field.Name=="ledger"||field.Name=="BirthNext"))continue;
                            Add(item.Key+"."+field.Name,field.GetValue(value));
                        }
                }
                long reachable=rows.Values.Sum(row=>row.StorageBytes);
                var unreachable=known.Where(pair=>!rows.ContainsKey(pair.Key)&&(int)Refs.GetValue(pair.Value)>0&&ReferenceEquals(Ledger.GetValue(pair.Value),budget)).Select(pair=>new Row{Id=pair.Key,References=(int)Refs.GetValue(pair.Value),Type=pair.Value.GetType().FullName,StorageBytes=pair.Value.StorageBytes,Path="known owner absent from current roots"}).ToArray();
                var added=rows.Values.Where(row=>!previous.ContainsKey(row.Id)).OrderBy(row=>row.Id).ToArray();var removed=previous.Values.Where(row=>!rows.ContainsKey(row.Id)).OrderBy(row=>row.Id).ToArray();
                var changed=rows.Values.Where(row=>previous.TryGetValue(row.Id,out var old)&&old.References!=row.References).Select(row=>new{row.Id,Before=previous[row.Id].References,After=row.References}).ToArray();
                bool unchanged=physical==budget.PhysicalBytes&&held==budget.HeldBytes&&scopes==budget.ActiveScopes;
                System.IO.File.WriteAllText(System.IO.Path.Combine(output,"ledger-"+(sequence++).ToString("D2")+"-"+phase+".json"),Newtonsoft.Json.JsonConvert.SerializeObject(new{Phase=phase,Physical=physical,Held=held,ActiveScopes=scopes,ReachableBytes=reachable,LedgerMinusReachable=physical-reachable,PhysicalDelta=physical-previousPhysical,ReachableDelta=reachable-previousReachable,AddedBytes=added.Sum(row=>row.StorageBytes),RemovedBytes=removed.Sum(row=>row.StorageBytes),Added=added,Removed=removed,ReferenceChanges=changed,Owners=rows.Values.OrderBy(row=>row.Id).ToArray(),KnownLedgerUnreachable=unreachable,CensusLedgerUnchanged=unchanged,RootPolicy="all session instance fields plus explicit private/frame/workspace/pins/scope-birth roots; no production getters"},Newtonsoft.Json.Formatting.Indented));
                TestContext.WriteLine("B12_LEDGER "+phase+" physical="+physical+" held="+held+" scopes="+scopes+" reachable="+reachable+" delta="+(physical-previousPhysical)+" added="+added.Sum(row=>row.StorageBytes)+" removed="+removed.Sum(row=>row.StorageBytes));
                previous=rows;previousPhysical=physical;previousReachable=reachable;
                Assert.True(unchanged,"field census must not change ledger");Assert.AreEqual(physical,reachable,"field census must account for every paid owner at "+phase);
            }
        }
        private static NavUnit Actor(NavigationSession s,int id)=>s.Crowd.Units.Single(a=>a.Id==id);
        private static byte[] Bytes(NavigationSession s){using(var state=s.CaptureOwnedState())return WorldWire.Pack(w=>WorldWire.Write(w,state));}
        private static void Destroy(NavigationSession s){if(s==null)return;s.ReleaseCommittedHostRoot();s.DestroyNavigationAuthority();Assert.Zero(s.PhysicalHostBudget.PhysicalBytes);Assert.Zero(s.PhysicalHostBudget.HeldBytes);Assert.Zero(s.PhysicalHostBudget.ActiveScopes);}
        private static NavigationSession Chain(NavObstacle[] obstacles=null)
        {
            var s=new NavigationSession(73,new NavGeometry(30,obstacles??Array.Empty<NavObstacle>(),1),PlayableProfile.Default.Navigation);
            for(int i=0;i<3;i++)s.Crowd.Add(i+1,new NavPoint(-5+i*Gap,0),Radius,4,4.5,canYield:true).Team=1;
            var waypoint=obstacles==null?new NavPoint(10,0):Actor(s,2).Position;
            Assert.Greater(waypoint.X-Actor(s,1).Position.X,Actor(s,1).Speed*Dt,"legal shorter wall waypoint leaves the identical full first step");
            Assert.True(s.Crowd.SetRoute(1,waypoint,new[]{waypoint}));return s;
        }
        [TestCase("hold")][TestCase("enemy")][TestCase("wall")][TestCase("zero-cap")]
        public void ChainStopsAtFrozenBarrierWithoutMovingPassiveReceivers(string barrier)
        {
            var wall=new NavObstacle(-1.96+Radius+.04,-3,-1.96+Radius+.14,3);
            var s=Chain(barrier=="wall"?new[]{wall}:null);try{
                if(barrier=="hold")s.Crowd.Stop(3,true);if(barrier=="enemy")Actor(s,3).Team=2;if(barrier=="zero-cap")s.Crowd.PreferMaxSpeed(3,0);
                var before=s.Crowd.Units.Select(a=>a.Position).ToArray();double heldHeading=Actor(s,3).Heading;
                s.Crowd.Step(Dt);for(int i=1;i<3;i++){Assert.AreEqual(before[i],Actor(s,i+1).Position,"barrier retracts chain; passive receiver cannot move");Assert.False(Actor(s,i+1).Moving);Assert.IsEmpty(Actor(s,i+1).Route);}Assert.AreEqual(heldHeading,Actor(s,3).Heading);
                Assert.Zero(s.PhysicalHostBudget.HeldBytes);Assert.Zero(s.PhysicalHostBudget.ActiveScopes);Assert.AreEqual(NavigationStorageOwnershipTests.UniqueWithSession(s),s.PhysicalHostBudget.PhysicalBytes);
            }finally{Destroy(s);}
        }
        [Test] public void YieldKeepsReceiversOwnRouteCursorGoalAndMovingIntent()
        {
            var s=Chain();try{var receiver=Actor(s,2);var goal=new NavPoint(-10,0);Assert.True(s.Crowd.SetRoute(2,goal,new[]{receiver.Position,goal}));var route=receiver.route;int cursor=receiver.routeIndex;var outcome=receiver.Outcome;
                s.Crowd.Step(Dt);Assert.Greater(receiver.Position.X,-3.48,"initiator physically displaces the own-order receiver");Assert.AreSame(route,receiver.route);Assert.AreEqual(cursor,receiver.routeIndex,"no own cursor advancement on yield-only frame");Assert.AreEqual(goal,receiver.Goal);Assert.True(receiver.Moving);Assert.AreEqual(outcome,receiver.Outcome);Assert.IsEmpty(Actor(s,3).Route);Assert.False(Actor(s,3).Moving);
            }finally{Destroy(s);}
        }
        [Test] public void PaidFrameContainsAllChainScratchAndStaleHoldCannotPublish()
        {
            var s=Chain();try{var budget=s.PhysicalHostBudget;long baseline=budget.PhysicalBytes;Assert.True(budget.TryOpenScope(NavigationPreparationKind.Admission,73,0,out var scope));using(scope){var f=NavPreparedCrowdStep.Create(s.Crowd,3,scope.OwnedReservation());try{
                    f.Observe();Assert.AreEqual(3,f.TerminalSeeds.Length);Assert.AreEqual(3,f.YieldLabels.Length);Assert.AreEqual(3,f.YieldQueue.Length);Assert.AreEqual(3,f.Motion.Length);Assert.AreEqual(NavigationStorageOwnershipTests.UniqueWithSession(s,f),budget.PhysicalBytes,"all private arrays and pins have a paid owner");
                    Assert.True(s.TryStopGroup(new[]{2},true));var held=Bytes(s);f.Compute(Dt);Assert.False(f.SourceCurrent(),"new HOLD invalidates prepared actor header/order");CollectionAssert.AreEqual(held,Bytes(s),"private stale compute cannot mutate live pose/order/cursor");
                }finally{f.Release();}}Assert.Zero(budget.HeldBytes);Assert.Zero(budget.ActiveScopes);Assert.AreEqual(NavigationStorageOwnershipTests.UniqueWithSession(s),budget.PhysicalBytes);Assert.Greater(baseline,0);
            }finally{Destroy(s);}
        }
        [Test] public void DeniedChainWorkspaceLeavesExactCurrentStateAndLedgerUnchanged()
        {
            var s=Chain();try{var before=Bytes(s);long bytes=s.PhysicalHostBudget.PhysicalBytes;int denied=0;s.PhysicalHostBudget.AllocationAdmission=_=>{denied++;return false;};try{Assert.Throws<InvalidOperationException>(()=>s.Crowd.Step(Dt));}finally{s.PhysicalHostBudget.AllocationAdmission=null;}
                Assert.Greater(denied,0);CollectionAssert.AreEqual(before,Bytes(s));Assert.AreEqual(bytes,s.PhysicalHostBudget.PhysicalBytes);Assert.Zero(s.PhysicalHostBudget.HeldBytes);Assert.Zero(s.PhysicalHostBudget.ActiveScopes);
            }finally{s.PhysicalHostBudget.AllocationAdmission=null;Destroy(s);}
        }
        private static NavigationSession Terminal(PlayableCommandKind kind,bool released,bool edge,bool assignedSeed=false)
        {
            var map=edge?ThreeCrossingsMap.Default:null;double z=edge?map.CentralBridgeWidth/2-Radius-.05:0;var geometry=new NavGeometry(map?.HalfExtent??30,map?.MovementBlockers.ToArray()??Array.Empty<NavObstacle>(),1);var s=new NavigationSession(73,geometry,PlayableProfile.Default.Navigation,terrain:map);
            for(int i=0;i<3;i++)s.Crowd.Add(i+1,new NavPoint((i-2)*Gap,z),Radius,4,4.5,canYield:true).Team=1;
            var goal=assignedSeed?new NavPoint(8,z):new NavPoint(.1,edge?map.CentralBridgeWidth/2-.15:0);
            NavLocation typed;if(map!=null){Assert.True(map.TryLocate(goal,0,out typed));Assert.False(map.IsValidLocation(typed,Radius),"point is valid while full circle centered at it crosses edge");Assert.True(map.SupportsFootprint(Actor(s,3).Position,Radius));}else typed=new NavLocation(goal,NavLocation.FlatSurface);
            var ids=new[]{1,2,3};var command=new PlayableCommand(73,77,"owner-11",kind,ids,goal).WithResolvedLocation(typed);s.PrepareCommandGroup(command,91,0,1);
            var goals=assignedSeed?new[]{Actor(s,1).Position,new NavPoint(5,z),new NavPoint(7,z)}:new[]{new NavPoint(3,z),new NavPoint(5,z),new NavPoint(7,z)};
            Assert.True(s.MoveGroup(ids,goals));s.FinishCommandGroup(true,ids);
            using(var host=new UnityHostRouteService()){var binding=new PlayableRouteBinding(geometry,PlayableProfile.Default,s.Admission,s.RoutePort);for(int i=0;i<4096&&s.PendingCount>0;i++){host.Service(binding,8);s.ApplyResults();}}
            Assert.Zero(s.PendingCount,"bounded real host route preparation");foreach(int id in ids){Assert.NotNull(s.InstalledExecutionFor(id));Assert.AreNotEqual(77,Actor(s,id).InstalledOrder,"navigation order and human command namespaces differ");if(released)s.SetFormationContact(id,true,1);}
            return s;
        }
        [TestCase(PlayableCommandKind.Move,false,false)][TestCase(PlayableCommandKind.AttackMove,true,false)]
        [TestCase(PlayableCommandKind.Move,true,true)][TestCase(PlayableCommandKind.AttackMove,false,true)]
        public void TypedCommonPointFootprintSettlesWholeBoundContactChain(PlayableCommandKind kind,bool released,bool edge)
