                var outside=s.Crowd.Add(1,new NavPoint(-3.48+.7,1.4),Radius,4,4.5);outside.Team=2;outside.Heading=-Math.PI/2;
                for(int i=0;i<3;i++)s.Crowd.Add(i+2,new NavPoint(-5+i*Gap,0),Radius,4,4.5,canYield:true).Team=1;
