        private static int StandaloneActivateYieldChains(NavPreparedCrowdStep frame,double dt,NavMotionBody[] bodies,NavMotionProposal[] proposals,int[] yieldLabels,int[] queue,int[] neighborCounts,bool cancelAdmitted11To10)
