        // Source-preparation helper for the adjacent1297->1298 capture only.
        // The caller must pay the projected NavUnit headers/body array through its
        // Projection reservation, copy EVERY post-marker header before this call,
        // retain the original frame/pins, and restore headers before actual Compute.
        // This helper does not run Compute, publish, Apply, change live headers,
        // replace routes, infer a historical carrier, or substitute a final goal.
        private static void ReconstructAdjacentPostMarkerRoutePrefix(NavPreparedCrowdStep frame,NavUnit[] projected,NavMotionBody[] motion,object transportGate)
        {
            Assert.NotNull(frame);Assert.NotNull(frame.Reservation);Assert.NotNull(projected);Assert.NotNull(motion);
            Assert.True(System.Threading.Monitor.IsEntered(transportGate),"actual transport gate owns post-marker source observations");Assert.True(frame.SourceCurrent());
            Assert.AreEqual(frame.After.Length,projected.Length);Assert.AreEqual(projected.Length,motion.Length);
            for(int i=0;i<projected.Length;i++){
                Assert.NotNull(projected[i]);Assert.AreEqual(frame.After[i].Id,projected[i].Id);
                Assert.True(projected[i].SameMovementValues(frame.After[i]),"input is the exact post-marker header, including route aliases and cursor/counter bits");
                Assert.IsNull(projected[i].StorageOwner,"scratch header must not carry a mutable live storage destination");
            }
            const System.Reflection.BindingFlags flags=System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic;
            var terrainClear=typeof(NavCrowd).GetMethod("TerrainClear",flags);
            var heldSegmentFree=typeof(NavCrowd).GetMethod("HeldSegmentFree",flags);
