                Cleanup("owners-headers-unique",()=>{if(nav==null||baseline<0)return;lock(gate){Assert.AreSame(sourceHost,Field("committedHostRoot"));Assert.AreSame(sourceTables,Field("liveArrivalTables"));for(int i=0;i<pins.Count;i++)Assert.AreEqual(pinRefs[i],References(pins[i]),"temporary observation pins released exactly");if(actorHeaders!=null)for(int i=0;i<actorHeaders.Length;i++){var a=nav.Crowd.Units[i];Assert.True(actorHeaders[i].SameMovementValues(a));Assert.AreSame(actorStorage[i],a.StorageOwner);Assert.AreSame(actorGlobal[i],a.StorageOwner.Global);Assert.AreSame(actorLocal[i],a.StorageOwner.Local);Assert.AreSame(actorInstalled[i],a.StorageOwner.InstalledExecution);Assert.AreEqual(actorDetached[i],a.StorageOwner.InstalledDetached);}}Assert.AreEqual(baseline,nav.PhysicalHostBudget.PhysicalBytes);Assert.AreEqual(baseline,NavigationStorageOwnershipTests.UniqueWithSession(nav));Assert.Zero(nav.PhysicalHostBudget.HeldBytes);Assert.Zero(nav.PhysicalHostBudget.ActiveScopes);ownersFooter=true;});
                Cleanup("destroy-zero",()=>{Destroy(nav);destroyFooter=nav!=null;});
                Cleanup("destroy-census",()=>{census?.Checkpoint("destroy");censusFooter=census!=null;});
                Cleanup("input-unchanged",()=>{if(bytes!=null){Assert.AreEqual("7fd497af032a5e320d175012250248ed7bf2ed80cc9c4e4cf29ecf5afde8c4a1",Hash(bytes));Assert.AreEqual(Hash(bytes),Hash(System.IO.File.ReadAllBytes(System.IO.Path.Combine(input,"before.bin"))));}});
                Cleanup("primitive-envelope-dispose",()=>envelope?.Dispose());
                Cleanup("metadata-result",()=>Save("metadata-result.json",new{SnapshotSaved=snapshotSaved,ObservationPassed=observationPassed&&currentFooter&&ownersFooter&&destroyFooter&&censusFooter&&primary==null&&cleanupErrors.Count==0,Qualified=false,GlobalPrefixQualified=false,ComputeCalls=0,PrivateCompute="NotRun",CarrierEquivalence="NotRun",CurrentBeforeBytesFooter=currentFooter,OwnersUniqueHeldScopesFooter=ownersFooter,DestroyZeroFooter=destroyFooter,CensusFooter=censusFooter,PrimaryException=primary?.ToString(),CleanupErrors=cleanupErrors.Select(e=>e.ToString()).ToArray(),Meaning="PASS means metadata observation and pristine footer only; earlier guarded FAIL and global gates unchanged"}));
            }
            if(primary!=null&&cleanupErrors.Count==0)System.Runtime.ExceptionServices.ExceptionDispatchInfo.Capture(primary).Throw();
            if(primary!=null)cleanupErrors.Insert(0,primary);if(cleanupErrors.Count!=0)throw new AggregateException("metadata observation primary/cleanup failures",cleanupErrors);
        }

    }
}
